  fd_fe64_sqr( v2, v ); fd_fe64_mul( v3, v2, v ); fd_fe64_sqr( v7, v3 ); fd_fe64_mul( v7, v7, v );
  fd_fe64_mul( uv7, u, v7 ); fd_fe64_pow22523( e, uv7 );
  fd_fe64_mul( r, u, v3 ); fd_fe64_mul( r, r, e );
  fd_fe64_sqr( r2, r ); fd_fe64_mul( vx2, v, r2 );
  if( fd_fe64_eq( vx2, u ) ) { memcpy( x, r, 32 ); return 1; }
  fd_fe64_neg( nu, u );
